typedef unsigned char u_char;
typedef unsigned short u_short;
typedef unsigned int u_int;
typedef unsigned long long u_long;

class nglFixedString
{
  char str[32];

public:
  typedef nglFixedString FS;

  const FS &operator=(const FS &rhs)
  {
    ((u_long *)str)[0] = ((const u_long *)rhs.str)[0];
    ((u_long *)str)[1] = ((const u_long *)rhs.str)[1];
    ((u_long *)str)[2] = ((const u_long *)rhs.str)[2];
    ((u_long *)str)[3] = ((const u_long *)rhs.str)[3];
    return *this;
  }

  const char *c_str() const
  {
    return str;
  }
};

class nglInstanceBank
{
public:
  struct Instance
  {
    nglFixedString Key;
    void *Value;
    int RefCount;
    Instance *Forward[1];
  };

  Instance *NIL;
  Instance *Head;

  Instance *Insert(const nglFixedString &, void *);
  Instance *Search(const nglFixedString &);
};

struct nglTexStreamPos
{
  u_int addr;
  u_int cycle;
};

struct nglFileBuf
{
  u_char *Buf;
  u_int Size;
  u_int UserData;
};

struct nglTexture
{
  nglTexStreamPos TexStreamPos;
  u_short Width;
  u_short Height;
  u_int Hash;
  u_char Type;
  u_char TW;
  u_char TH;
  u_char type_pad;
  struct
  {
    u_int LoadedInPlace : 1;
    u_int Locked : 1;
    u_int VRAMOnly : 1;
    u_int System : 1;
    u_int RenderTarget : 1;
  } Flags;
  void *ph;
  u_int Format;
  u_int *Data;
  u_int NFrames;
  nglTexture **Frames;
  u_int SrcDataSize;
  nglFileBuf FileBuf;
  nglFixedString FileName;
  char remaining[208];
};

enum
{
  NGLTEX_TGA,
  NGLTEX_TIM2,
  NGLTEX_IFL,
  NGLTEX_ATE
};

extern nglInstanceBank nglTextureBank;
extern void *nglMemAlloc(u_int Size, u_int Align = 1);
extern void nglMemFree(void *);
extern void *memset(void *, int, u_int);
extern int rand();
extern void nglWarning(const char *, ...);
extern bool nglLoadTextureATE(
  nglTexture *, u_char *, const nglFixedString &);
extern bool nglLoadTextureIFL(nglTexture *, u_char *, u_int);
extern bool nglLoadTextureTGA(nglTexture *, u_char *);
extern bool nglLoadTextureTM2(nglTexture *, u_char *);

nglTexture *nglLoadTextureInPlace(
  const nglFixedString &FileName, u_int Type, void *Data, u_int Size)
{
  bool Result = false;

  nglInstanceBank::Instance *Inst;
  if ((Inst = nglTextureBank.Search(FileName)))
  {
    Inst->RefCount++;
    return (nglTexture *)Inst->Value;
  }

  nglTexture *Tex = (nglTexture *)nglMemAlloc(sizeof(nglTexture));
  memset(Tex, 0, sizeof(nglTexture));

  switch (Type)
  {
    case NGLTEX_TIM2:
      Result = nglLoadTextureTM2(Tex, (u_char *)Data);
      break;
    case NGLTEX_TGA:
      Result = nglLoadTextureTGA(Tex, (u_char *)Data);
      break;
    case NGLTEX_IFL:
      Result = nglLoadTextureIFL(Tex, (u_char *)Data, Size);
      break;
    case NGLTEX_ATE:
      Result = nglLoadTextureATE(Tex, (u_char *)Data, FileName);
      break;
  }

  if (!Result)
  {
    nglWarning(
      "nglLoadTextureInPlace: Unable to parse %s.\n", FileName.c_str());
    nglMemFree(Tex);
    return 0;
  }

  Tex->FileName = FileName;
  Tex->Flags.Locked = 0;
  Tex->TexStreamPos.addr = 0;
  Tex->TexStreamPos.cycle = 0;
  Tex->Flags.LoadedInPlace = true;
  Tex->Hash = rand();

  Tex->FileBuf.Buf = (u_char *)Data;
  Tex->FileBuf.Size = Size;

  nglTextureBank.Insert(Tex->FileName, Tex);

  return Tex;
}
